"""Genera ``FormatoLandmarks.g.cs`` (constantes del formato para la app Unity)."""

from __future__ import annotations

from pathlib import Path

from . import formato as F

RUTA_UNITY = (
    Path(__file__).resolve().parents[2]
    / "unity" / "LSRD-AR" / "Assets" / "LSRD" / "Scripts" / "Nucleo" / "FormatoLandmarks.g.cs"
)


def _arreglo(valores) -> str:
    return "{ " + ", ".join(str(int(v)) for v in valores) + " }"


def generar() -> str:
    huesos = [i for par in F.HUESOS for i in par]
    lineas = [
        "// <auto-generated>",
        "// Generado por ml/scripts/generar_csharp.py a partir de ml/lsrd_ml/formato.py.",
        "// No editar a mano: cambie formato.py y vuelva a generar.",
        "// </auto-generated>",
        "",
        "namespace LSRD.Nucleo",
        "{",
        "    /// <summary>Constantes del formato de puntos clave " + F.VERSION + ".</summary>",
        "    public static class FormatoLandmarks",
        "    {",
        f'        public const string Version = "{F.VERSION}";',
        f"        public const int NPuntos = {F.N_PUNTOS};",
        f"        public const int NCoordenadas = {F.N_COORDENADAS};",
        f"        public const int ValoresPorCuadro = {F.N_PUNTOS * F.N_COORDENADAS};",
        f"        public const int LongitudSecuencia = {F.LONGITUD_SECUENCIA};",
        f"        public const int PuntosMano = {F.PUNTOS_MANO};",
        f"        public const int ManoMuneca = {F.MANO_MUNECA};",
        f"        public const int ManoBaseMedio = {F.MANO_BASE_MEDIO};",
        "",
        f"        public const int InicioPose = {F.INICIO_POSE};",
        f"        public const int InicioManoIzq = {F.INICIO_MANO_IZQ};",
        f"        public const int InicioManoDer = {F.INICIO_MANO_DER};",
        f"        public const int InicioCara = {F.INICIO_CARA};",
        "",
        f"        public const int IdxNariz = {F.IDX_NARIZ};",
        f"        public const int IdxHombroIzq = {F.IDX_HOMBRO_IZQ};",
        f"        public const int IdxHombroDer = {F.IDX_HOMBRO_DER};",
        f"        public const int IdxMunecaIzq = {F.IDX_MUNECA_IZQ};",
        f"        public const int IdxMunecaDer = {F.IDX_MUNECA_DER};",
        f"        public const int IdxCaraReferencia = {F.IDX_CARA_REFERENCIA};",
        "",
        "        /// <summary>Índices de MediaPipe Pose (33 puntos) que se conservan, en orden.</summary>",
        f"        public static readonly int[] PoseIndicesMediapipe = {_arreglo(F.POSE_INDICES_MEDIAPIPE)};",
        "",
        "        /// <summary>Índices de MediaPipe Face Mesh que se conservan, en orden.</summary>",
        f"        public static readonly int[] CaraIndicesMediapipe = {_arreglo(F.CARA_INDICES_MEDIAPIPE)};",
        "",
        "        /// <summary>Permutación de puntos para un espejo horizontal.</summary>",
        f"        public static readonly int[] PermutacionEspejo = {_arreglo(F.PERMUTACION_ESPEJO)};",
        "",
        "        /// <summary>Pares (a, b) consecutivos de índices canónicos que forman huesos para dibujar.</summary>",
        f"        public static readonly int[] Huesos = {_arreglo(huesos)};",
        "    }",
        "}",
        "",
    ]
    return "\n".join(lineas)


def escribir(ruta: Path = RUTA_UNITY) -> Path:
    ruta.parent.mkdir(parents=True, exist_ok=True)
    ruta.write_text(generar(), encoding="utf-8")
    return ruta
